CREATE TABLE `pagos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `empresa_id` bigint unsigned NOT NULL,
  `padre_familia_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `pago_concepto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `monto_pago` decimal(10,2) NOT NULL,
  `modalidad` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONTADO',
  `numero_cuota` int NOT NULL DEFAULT '1',
  `total_cuotas` int NOT NULL DEFAULT '1',
  `saldo_pendiente` decimal(10,2) NOT NULL DEFAULT '0.00',
  `faena_id` bigint unsigned DEFAULT NULL,
  `debe` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tipo_comprobante` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOTA_VENTA',
  `es_regularizacion` tinyint(1) NOT NULL DEFAULT '0',
  `recibo_manual_referencia` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serie` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_facturacion` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDIENTE',
  `hash_cpe` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mensaje_sunat` text COLLATE utf8mb4_unicode_ci,
  `pdf_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `xml_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_pago_empresa_serie_numero` (`empresa_id`,`serie`,`numero`),
  KEY `pagos_padre_familia_id_foreign` (`padre_familia_id`),
  KEY `pagos_user_id_foreign` (`user_id`),
  KEY `pagos_faena_id_index` (`faena_id`),
  KEY `pagos_empresa_padre_index` (`empresa_id`,`padre_familia_id`),
  CONSTRAINT `pagos_empresa_id_foreign` FOREIGN KEY (`empresa_id`) REFERENCES `empresas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagos_padre_familia_id_foreign` FOREIGN KEY (`padre_familia_id`) REFERENCES `padres_familia` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagos_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
