DROP TABLE IF EXISTS `talleres`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `talleres` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `empresa_id` bigint unsigned NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `nivel` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Todos',
  `grado` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Todos',
  `seccion` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Todas',
  `turno` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tarde',
  `hora_inicio` time NOT NULL DEFAULT '14:30:00',
  `hora_limite_puntual` time NOT NULL DEFAULT '14:45:00',
  `hora_fin` time NOT NULL DEFAULT '16:30:00',
  `dias_semana` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Lunes,Miércoles,Viernes',
  `docente_responsable` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lugar` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `talleres_empresa_academico_idx` (`empresa_id`,`nivel`,`grado`,`seccion`),
  CONSTRAINT `talleres_empresa_id_foreign` FOREIGN KEY (`empresa_id`) REFERENCES `empresas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
